def choose_move(observation):
    sx, sy = observation.get("self_position", (0, 0))
    ox, oy = observation.get("opponent_position", (0, 0))
    env = observation.get("environment_name", "resource_collection")

    # Defensive extraction
    def safe_get(lst, idx, default=0):
        return lst[idx] if lst and len(lst) > idx and lst[idx] is not None else default

    # Helper to decide move towards a target
    def move_towards(target_x, target_y):
        dx = 0
        dy = 0
        if target_x > sx:
            dx = 1
        elif target_x < sx:
            dx = -1
        if target_y > sy:
            dy = 1
        elif target_y < sy:
            dy = -1
        return [dx, dy]

    # For pursuit_evasion
    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            # Pursue opponent
            return move_towards(ox, oy)
        else:
            # Evade opponent
            dx, dy = move_towards(ox, oy)
            return [-dx, -dy]

    # For territory_control
    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or []
        if not targets:
            return [0, 0]
        best = min(targets, key=lambda item: abs(item[0] - sx) + abs(item[1] - sy))
        return move_towards(best[0], best[1])

    # For resource_collection
    resources = observation.get("resources") or []
    if resources:
        best = min(resources, key=lambda item: abs(item[0] - sx) + abs(item[1] - sy))
        return move_towards(best[0], best[1])

    # Default: move towards opponent
    return move_towards(ox, oy)

